def decide(selected, sources):
    fields = selected['facts']
    invalid = []
    for field, spans in fields.items():
        for span in spans:
            source = span.get('source')
            if source not in sources or not span.get('quote') or span['quote'] not in sources[source]:
                invalid.append({'field': field, 'span': span})
    missing = [field for field in ('problem', 'outcome', 'acceptance') if not fields.get(field)]
    if selected['kind'] == 'product':
        missing += [field for field in ('beneficiary', 'urgency', 'alternative', 'displaced_work') if not fields.get(field)]
    missing += selected['other_required_missing']
    ready = not missing and not invalid and selected['kind'] in ('product', 'engineering')
    return {'ready': ready, 'missing': missing, 'invalid_spans': invalid,
            'kind': selected['kind'], 'explicit_hold': selected['explicit_hold']}
